<?php
namespace App\Http\Controllers\Api\V1;use App\Models\PortfolioCategory;use Illuminate\Http\Request;class PortfolioCategoryController extends ApiController{public function index(){return $this->success(PortfolioCategory::where('status','ACTIVE')->orderBy('sort_order')->get());}public function store(Request $r){$this->admin($r);$d=$r->validate(['name'=>'required|string|max:255|unique:portfolio_categories,name','description'=>'nullable|string','status'=>'nullable|in:ACTIVE,INACTIVE','sort_order'=>'nullable|integer|min:0']);return $this->success(PortfolioCategory::create($d));}public function update(Request $r,PortfolioCategory $category){$this->admin($r);$d=$r->validate(['name'=>'sometimes|string|max:255|unique:portfolio_categories,name,'.$category->id,'description'=>'nullable|string','status'=>'nullable|in:ACTIVE,INACTIVE','sort_order'=>'nullable|integer|min:0']);$category->update($d);return $this->success($category->fresh());}private function admin(Request $r){abort_unless($r->user()->roles()->whereIn('name',['ADMIN','SUPER_ADMIN'])->exists(),403);}}
